// Lógica completa de atendimento WhatsApp
const message = $input.all()[0].json;

// VALIDAÇÃO CRÍTICA: Verificar se a requisição contém dados válidos de WhatsApp
if (!message || !message.key || !message.key.remoteJid) {
  return [];
}

const remoteJid = message.key.remoteJid;

// Validar se remoteJid não está vazio e é um número válido
if (!remoteJid || typeof remoteJid !== 'string' || remoteJid.trim() === '') {
  return [];
}

// Filtro: ignorar mensagens próprias e grupos
if (message.key.fromMe === true || remoteJid.includes('@g.us')) {
  return [];
}

const messageText = message.message && message.message.conversation ? message.message.conversation : '';
const textLower = messageText.toLowerCase().trim();

// Configurações
const evolutionApiUrl = 'https://api.pracinha.online';
const instanceName = 'Variant';
const apiKey = '429683C4C977415CAAFCCE10F7D57E11';
const cardapioLink = 'cardapio-cidadela.vercel.app';

// Detectar rota e preparar resposta
let responseText = '';

if (textLower === '1' || textLower === '1️⃣') {
  responseText = `Acesse nosso cardápio no link abaixo para escolher seus itens e fazer o pedido: ${cardapioLink}`;
} else if (textLower === '2' || textLower === '2️⃣') {
  responseText = 'Perfeito! Lembramos que a nossa taxa de visita técnica é de R$ 100,00 (mais o valor do serviço a ser executado).\n\nPor favor, informe seu nome completo:';
} else if (textLower === '3' || textLower === '3️⃣') {
  responseText = `🎮 Acesse a Arena de Batalha da Cidadela: ${cardapioLink}/cidadela/battle\n\nJogue online contra outros pracinhas!`;
} else {
  responseText = 'Olá! Seja bem-vindo(a). Por favor, responda digitando o número da opção desejada:\n\n1️⃣ - Cardápio / Fazer Pedido\n2️⃣ - Assistência Técnica\n3️⃣ - Arena de Batalha (Jogos Online)';
}

return [{
  json: {
    evolutionApiUrl,
    instanceName,
    apiKey,
    number: remoteJid,
    text: responseText
  }
}];

// Processar pedido do cardápio
const payload = $input.all()[0].json;

// Validar campos obrigatórios
const required = ['cliente', 'telefone', 'endereco', 'total', 'itens', 'tipo_entrega', 'origem', 'comanda', 'evento', 'timestamp', 'pagamento'];
const missing = required.filter(f => !payload[f]);

if (missing.length > 0 || payload.origem !== 'CIDADELA_PWA') {
  return [{
    json: {
      success: false,
      error: 'validation_error',
      message: 'Dados inválidos'
    }
  }];
}

// Configurações Evolution API
const evolutionApiUrl = 'https://api.pracinha.online';
const instanceName = 'Variant';
const apiKey = '429683C4C977415CAAFCCE10F7D57E11';
const restauranteNumber = payload.restaurante_whatsapp || '5548999880030';

// Formatar mensagem comanda
let pagamentoText = payload.pagamento;
if (payload.pagamento === 'dinheiro') pagamentoText = `Dinheiro (Troco p/ R$ ${payload.troco || '0'})`;
else if (payload.pagamento === 'cartao') pagamentoText = 'Cartão';

const itensText = payload.itens.map(i => `- ${i.quantity}x ${i.name} (R$ ${i.total.toFixed(2)})${i.observacoes ? `\n  _Obs: ${i.observacoes}_` : ''}`).join('\n');
const enderecoText = payload.tipo_entrega === 'entrega' ? payload.endereco : 'Retirada no balcão';
const tipoText = payload.tipo_entrega === 'entrega' ? 'Delivery' : 'Retirada';

const mensagem = `==============================\n   *NOVO PEDIDO - CIDADELA*\n==============================\n*Cliente:* ${payload.cliente}\n*Telefone:* ${payload.telefone}\n*Tipo:* ${tipoText}\n*Endereço:* ${enderecoText}\n\n------------------------------\n*ITENS DO PEDIDO:*\n${itensText}\n------------------------------\n\n*FORMA DE PAGAMENTO:* ${pagamentoText}\n*TAXA DE ENTREGA:* R$ ${payload.taxa_entrega.toFixed(2)}\n*TOTAL DO PEDIDO:* R$ ${payload.total.toFixed(2)}\n==============================`;

return [{
  json: {
    success: true,
    comanda: payload.comanda,
    mensagem_formatada: mensagem,
    pedido: payload,
    cliente_number: payload.telefone,
    restaurante_number: restauranteNumber,
    evolutionApiUrl,
    instanceName,
    apiKey
  }
}];

// Validar código de autenticação
const payload = $input.all()[0].json;

if (!payload.codigo || payload.origem !== 'CIDADELA_PWA') {
  return [{
    json: {
      success: false,
      autenticado: false,
      erro: 'invalid_code'
    }
  }];
}

// Simular validação (em produção usar banco real)
const validCodes = {
  'ADMIN123': { nivel: 'admin' },
  'OPER456': { nivel: 'operador' }
};

const codeData = validCodes[payload.codigo];
if (!codeData) {
  return [{
    json: {
      success: false,
      autenticado: false,
      erro: 'invalid_code'
    }
  }];
}

const token = Buffer.from(`${payload.codigo}_${Date.now()}`).toString('base64');

return [{
  json: {
    success: true,
    autenticado: true,
    nivel_acesso: codeData.nivel,
    token_sessao: token,
    expiracao: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
  }
}];

// Processar eventos de sessão de jogo
const payload = $input.all()[0].json;

const supabaseUrl = 'https://seu-projeto.supabase.co';
const supabaseKey = 'sua-chave-anon-publica';
const evolutionApiUrl = 'https://api.pracinha.online';
const instanceName = 'Variant';
const apiKey = '429683C4C977415CAAFCCE10F7D57E11';

// Validar campos obrigatórios
if (!payload.acao || !payload.game_type) {
  return [{
    json: {
      success: false,
      error: 'missing_fields',
      message: 'Campos obrigatórios: acao, game_type'
    }
  }];
}

const acao = payload.acao; // 'criar', 'entrar', 'atualizar', 'completar'
const gameType = payload.game_type; // 'battle', 'trilha', 'iq_test'

let result = { success: false };
let whatsappNotification = null;

if (acao === 'criar') {
  // Criar nova sessão de jogo
  const sessionData = {
    game_type: gameType,
    player1_id: payload.player1_id,
    player1_name: payload.player1_name || 'Player 1',
    player1_data: payload.player1_data || {},
    status: 'waiting',
    current_turn: 1,
    game_state: payload.game_state || {}
  };

  // Em produção: fazer POST para Supabase REST API
  result = {
    success: true,
    acao: 'criar',
    session_id: 'temp_' + Date.now(),
    message: 'Sessão criada com sucesso'
  };

} else if (acao === 'entrar') {
  // Entrar em sessão existente
  if (!payload.session_id) {
    return [{
      json: {
        success: false,
        error: 'missing_session_id'
      }
    }];
  }

  // Em produção: fazer UPDATE para Supabase
  result = {
    success: true,
    acao: 'entrar',
    session_id: payload.session_id,
    message: 'Entrou na sessão com sucesso'
  };

  // Notificar player1 via WhatsApp se tiver número
  if (payload.player1_phone) {
    whatsappNotification = {
      number: payload.player1_phone,
      text: `⚔️ Oponente encontrado!\n\nJogador: ${payload.player2_name || 'Player 2'}\nJogo: ${gameType}\n\nA batalha vai começar!`
    };
  }

} else if (acao === 'atualizar') {
  // Atualizar estado do jogo
  if (!payload.session_id) {
    return [{
      json: {
        success: false,
        error: 'missing_session_id'
      }
    }];
  }

  result = {
    success: true,
    acao: 'atualizar',
    session_id: payload.session_id,
    message: 'Estado atualizado'
  };

} else if (acao === 'completar') {
  // Completar jogo
  if (!payload.session_id || !payload.winner) {
    return [{
      json: {
        success: false,
        error: 'missing_fields'
      }
    }];
  }

  result = {
    success: true,
    acao: 'completar',
    session_id: payload.session_id,
    winner: payload.winner,
    message: 'Jogo completado'
  };

  // Notificar ambos os jogadores se tiver números
  if (payload.player1_phone) {
    whatsappNotification = {
      number: payload.player1_phone,
      text: `🏆 Jogo Finalizado!\n\nVencedor: ${payload.winner}\nJogo: ${gameType}\n\nParabéns aos combatentes!`
    };
  }
}

return [{
  json: {
    ...result,
    whatsappNotification,
    evolutionApiUrl,
    instanceName,
    apiKey
  }
}];

// Enviar notificação WhatsApp se houver
const data = $input.all()[0].json;

if (!data.whatsappNotification) {
  return [];
}

return [{
  json: {
    evolutionApiUrl: data.evolutionApiUrl,
    instanceName: data.instanceName,
    apiKey: data.apiKey,
    number: data.whatsappNotification.number,
    text: data.whatsappNotification.text
  }
}];

// Processar movimentos/jogadas de jogo
const payload = $input.all()[0].json;

const supabaseUrl = 'https://seu-projeto.supabase.co';
const supabaseKey = 'sua-chave-anon-publica';

// Validar campos obrigatórios
if (!payload.session_id || !payload.player_id || !payload.move_type) {
  return [{
    json: {
      success: false,
      error: 'missing_fields',
      message: 'Campos obrigatórios: session_id, player_id, move_type'
    }
  }];
}

const moveData = {
  session_id: payload.session_id,
  player_id: payload.player_id,
  player_number: payload.player_number || 1,
  move_type: payload.move_type,
  move_data: payload.move_data || {},
  round_number: payload.round_number || 1
};

// Em produção: fazer POST para Supabase REST API
// POST /rest/v1/game_moves

return [{
  json: {
    success: true,
    move_id: 'move_' + Date.now(),
    message: 'Movimento registrado com sucesso',
    move: moveData
  }
}];

// Processar criação de trial administrativo
const payload = $input.all()[0].json;

const evolutionApiUrl = 'https://api.pracinha.online';
const instanceName = 'Variant';
const apiKey = '429683C4C977415CAAFCCE10F7D57E11';

// Validar campos obrigatórios
if (!payload.acao || payload.acao !== 'criar_trial' || !payload.store_name || !payload.admin_phone) {
  return [{
    json: {
      success: false,
      error: 'missing_fields',
      message: 'Campos obrigatórios: acao, store_name, admin_phone'
    }
  }];
}

// Gerar código de acesso
const accessCode = `FEB-${Math.random().toString(36).toUpperCase().slice(2, 8)}-TRIAL`;

// Calcular data de expiração (2 dias)
const trialStartedAt = new Date();
const trialExpiresAt = new Date(trialStartedAt);
trialExpiresAt.setDate(trialExpiresAt.getDate() + 2);

// Em produção: salvar no Supabase
// POST /rest/v1/admin_trials

return [{
  json: {
    success: true,
    access_code: accessCode,
    trial_expires_at: trialExpiresAt.toISOString(),
    message: 'Trial criado com sucesso',
    store_name: payload.store_name,
    admin_phone: payload.admin_phone,
    evolutionApiUrl,
    instanceName,
    apiKey
  }
}];

// Enviar WhatsApp com código de acesso
const data = $input.all()[0].json;

if (!data.success || !data.access_code) {
  return [];
}

const mensagem = `🎉 *TRIAL CRIADO COM SUCESSO!*\n\n📱 *Loja:* ${data.store_name}\n🔑 *Código de Acesso:* ${data.access_code}\n⏰ *Expira em:* 2 dias\n\nUse este código para acessar o painel administrativo.\n\nApós expirar, entre em contato para obter o código definitivo de 1 ano.`;

return [{
  json: {
    evolutionApiUrl: data.evolutionApiUrl,
    instanceName: data.instanceName,
    apiKey: data.apiKey,
    number: data.admin_phone,
    text: mensagem
  }
}];
